import {
  ONBOARDING_STEP_KEYS,
  ONBOARDING_STEP_LABELS,
  type BankStepInput,
  type DocsStepInput,
  type EsignInput,
  type KitStepInput,
  type OnboardingDto,
  type OnboardingListRow,
  type OnboardingStepKey,
  type OnboardingTemplates,
} from '@lexisora/shared';
import { AuditService } from '../../../core/audit/audit.service';
import { requireContext } from '../../../core/context/request-context';
import { CryptoService } from '../../../core/crypto/crypto.service';
import { AppError, badRequest, notFound } from '../../../core/http/errors';
import { NotificationsService } from '../../../core/notifications/notifications.service';
import { PrismaService } from '../../../core/prisma/prisma.service';
import { EventsService } from '../../../core/registry/events.service';
import { SettingsService } from '../../../core/settings/settings.service';
import { loadCompensation } from '../compensation';
import { EsignService } from '../documents/esign.service';
import { mergeFields, type EsignDocData } from '../documents/esign-render';
import { VaultService } from '../documents/vault.service';
import { IdCardsService } from '../idcards/idcards.service';
import { KitsService } from '../kits/kits.service';
import {
  applyOnboardingEvent,
  currentStep,
  incompleteSteps,
  isValidAadhaar,
  isValidPan,
  lookupIfsc,
  maskAccount,
  maskPan,
  namesMatch,
  OnboardingRuleError,
  validateBank,
  type ObEvent,
  type ObKey,
  type ObStatus,
  type ObStepStatus,
} from '../people.rules';
import { dbDateKey, fmt, inrPdf } from '../people.util';

const TEMPLATES_KEY = 'people.onboarding.templates';
const VERIFY_TYPES = ['PAN', 'AADHAAR', 'MARKSHEET_10', 'MARKSHEET_12', 'DEGREE', 'PREV_EMPLOYMENT', 'CANCELLED_CHEQUE'] as const;

export const DEFAULT_TEMPLATES: OnboardingTemplates = {
  offerBody:
    'Dear {{firstName}},\n\nThis letter confirms your appointment at {{company}} as {{designation}} in the {{department}} team, with effect from {{joiningDate}}, with the compensation shown in Annexure A.\n\nYou will report to {{manager}} and work in {{workMode}} mode under the General shift. Your employment is governed by the company policies published on the HRMS, including the attendance, leave and information-security policies.\n\nPlease sign below to accept this offer. We look forward to working with you.',
  ndaBody:
    'This Non-Disclosure Agreement is made between {{company}} and {{fullName}} ({{empCode}}).\n\nYou agree to keep client code, data and business information confidential during and after employment, to use it only for your work at {{company}}, and not to copy it to personal devices or accounts.\n\nOn leaving the company you will return or destroy all confidential material in your possession. This obligation survives the end of your employment.',
  signatoryName: 'Kavya Iyer',
  signatoryTitle: 'HR Manager',
};

const STATUS_LABEL: Record<string, string> = {
  NOT_STARTED: 'Not started',
  IN_PROGRESS: 'In progress',
  SUBMITTED: 'Submitted · verifying',
  COMPLETED: 'Completed',
  CANCELLED: 'Cancelled',
};

type ObWithSteps = Onboarding & { steps: OnboardingStep[] };

/** Paperless onboarding (M5): 5 steps, local e-sign, documents, bank & tax, welcome kit. */
@Injectable()
export class OnboardingService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly esign: EsignService,
    private readonly vault: VaultService,
    private readonly kits: KitsService,
    private readonly idcards: IdCardsService,
    private readonly crypto: CryptoService,
    private readonly settings: SettingsService,
    private readonly notify: NotificationsService,
    private readonly audit: AuditService,
    private readonly events: EventsService,
  ) {}

  // ── Templates ────────────────────────────────────────────────────────────

  templates(): Promise<OnboardingTemplates> {
    return this.settings.get<OnboardingTemplates>(TEMPLATES_KEY, DEFAULT_TEMPLATES);
  }

  async saveTemplates(t: OnboardingTemplates) {
    await this.settings.set(TEMPLATES_KEY, t);
    await this.audit.record({ action: 'onboarding.templates_updated', entity: 'Setting', entityId: TEMPLATES_KEY });
    return this.templates();
  }

  // ── Creation ─────────────────────────────────────────────────────────────

  async createFor(employeeId: string) {
    const existing = await this.prisma.onboarding.findUnique({ where: { employeeId } });
    if (existing) return existing;
    const tenantId = requireContext().tenantId;
    const ob = await this.prisma.onboarding.create({
      data: {
        employeeId,
        status: 'NOT_STARTED',
        steps: { create: ONBOARDING_STEP_KEYS.map((key, i) => ({ tenantId, key, order: i + 1, status: 'PENDING' as const })) },
      } as Prisma.OnboardingUncheckedCreateInput,
    });
    await this.audit.record({ action: 'onboarding.created', entity: 'Onboarding', entityId: ob.id, meta: { employeeId } });
    return ob;
  }

  private async load(employeeId: string): Promise<ObWithSteps | null> {
    return this.prisma.onboarding.findUnique({ where: { employeeId }, include: { steps: { orderBy: { order: 'asc' } } } });
  }

  private async mustLoad(employeeId: string): Promise<ObWithSteps> {
    const ob = await this.load(employeeId);
    if (!ob) throw notFound('Onboarding');
    return ob;
  }

  private stepMap(ob: ObWithSteps): Record<ObKey, ObStepStatus> {
    const m = Object.fromEntries(ONBOARDING_STEP_KEYS.map((k) => [k, 'PENDING'])) as Record<ObKey, ObStepStatus>;
    for (const s of ob.steps) m[s.key as ObKey] = s.status as ObStepStatus;
    return m;
  }

  /** Apply a state-machine event and persist the changed statuses. */
  private async apply(ob: ObWithSteps, ev: ObEvent, stepPatch: Partial<Record<ObKey, { data?: Prisma.InputJsonValue; note?: string | null; envelopeId?: string | null }>> = {}) {
    let next: { status: ObStatus; steps: Record<ObKey, ObStepStatus> };
    try {
      next = applyOnboardingEvent(ob.status as ObStatus, this.stepMap(ob), ev);
    } catch (e) {
      if (e instanceof OnboardingRuleError) throw new AppError(409, e.code, e.message, e.details);
      throw e;
    }
    const now = new Date();
    for (const s of ob.steps) {
      const key = s.key as ObKey;
      const patch = stepPatch[key];
      const newStatus = next.steps[key];
      if (newStatus === s.status && !patch) continue;
      await this.prisma.onboardingStep.update({
        where: { id: s.id },
        data: {
          status: newStatus,
          completedAt: newStatus === 'DONE' ? (s.completedAt ?? now) : newStatus === 'NEEDS_ATTENTION' ? null : s.completedAt,
          ...(patch?.data !== undefined ? { data: patch.data } : {}),
          ...(patch?.note !== undefined ? { note: patch.note } : newStatus === 'DONE' ? { note: null } : {}),
          ...(patch?.envelopeId !== undefined ? { esignEnvelopeId: patch.envelopeId } : {}),
        },
      });
    }
    await this.prisma.onboarding.update({
      where: { id: ob.id },
      data: {
        status: next.status,
        startedAt: ob.startedAt ?? (next.status !== 'NOT_STARTED' ? now : null),
        submittedAt: next.status === 'SUBMITTED' && ob.status !== 'SUBMITTED' ? now : ob.submittedAt,
        completedAt: next.status === 'COMPLETED' ? (ob.completedAt ?? now) : ob.completedAt,
      },
    });
    return next;
  }

  // ── Documents (offer letter, NDA) ────────────────────────────────────────

  private async docData(employeeId: string, kind: 'OFFER' | 'NDA'): Promise<EsignDocData> {
    const e = await this.prisma.employee.findUniqueOrThrow({ where: { id: employeeId }, include: { designation: true, department: true, manager: { select: { fullName: true } } } });
    const t = await this.prisma.raw.tenant.findUniqueOrThrow({ where: { id: requireContext().tenantId } });
    const tpl = await this.templates();
    const fields: Record<string, string> = {
      firstName: e.firstName,
      fullName: e.fullName,
      empCode: e.empCode,
      company: t.name,
      designation: e.designation?.name ?? 'your role',
      department: e.department?.name ?? '',
      joiningDate: fmt(e.joiningDate),
      manager: e.manager?.fullName ?? 'your reporting manager',
      workMode: e.workMode === 'OFFICE' ? 'office' : e.workMode === 'REMOTE' ? 'remote' : 'hybrid',
    };
    const body = mergeFields(kind === 'OFFER' ? tpl.offerBody : tpl.ndaBody, fields);
    let annexure: EsignDocData['annexure'] = null;
    let annexureNote: string | null = null;
    if (kind === 'OFFER') {
      const comp = await loadCompensation(this.prisma, this.crypto, employeeId);
      if (comp) annexure = comp.rows.map((r) => ({ component: r.component, monthly: inrPdf(r.monthlyPaise), annual: inrPdf(r.annualPaise), isTotal: r.isTotal }));
      else annexureNote = 'Your compensation structure is being finalised by Payroll; HR will share Annexure A separately.';
    }
    return {
      kind,
      company: t.legalName ?? t.name,
      companyAddress: [t.address, t.city, t.stateName].filter(Boolean).join(', ') || null,
      title: kind === 'OFFER' ? `Offer letter · ${e.designation?.name ?? e.fullName}` : 'Non-disclosure agreement',
      dateLabel: fmt(new Date()),
      employee: { name: e.fullName, designation: e.designation?.name ?? null, department: e.department?.name ?? null, empCode: e.empCode, joiningDate: dbDateKey(e.joiningDate), email: e.officialEmail },
      paragraphs: body.split(/\n\s*\n/).map((p) => p.replace(/\n/g, ' ').trim()).filter(Boolean),
      annexure,
      annexureNote,
      signatory: { name: tpl.signatoryName, title: tpl.signatoryTitle },
    };
  }

  /** Make sure the offer / NDA envelopes exist for unsigned steps (regenerates when Annexure A became available). */
  private async ensureEnvelopes(ob: ObWithSteps) {
    const e = await this.prisma.employee.findUniqueOrThrow({ where: { id: ob.employeeId }, include: { user: true } });
    for (const [key, kind] of [['offer', 'OFFER'], ['nda', 'NDA']] as const) {
      const step = ob.steps.find((s) => s.key === key);
      if (!step || step.status === 'DONE' || step.status === 'SKIPPED') continue;
      let env = step.esignEnvelopeId ? await this.prisma.esignEnvelope.findUnique({ where: { id: step.esignEnvelopeId } }) : null;
      const stale = env && kind === 'OFFER' && !(env.docData as unknown as EsignDocData).annexure && (await loadCompensation(this.prisma, this.crypto, ob.employeeId));
      if (env && (['VOIDED', 'EXPIRED', 'DECLINED'].includes(env.status) || stale)) {
        if (stale) await this.esign.voidEnvelope(env.id);
        env = null;
      }
      if (!env) {
        const doc = await this.docData(ob.employeeId, kind);
        env = await this.esign.create({ purpose: kind, title: doc.title, subjectEmployeeId: e.id, doc, signerName: e.fullName, signerEmail: e.personalEmail ?? e.officialEmail, signerUserId: e.userId });
        await this.prisma.onboardingStep.update({ where: { id: step.id }, data: { esignEnvelopeId: env.id } });
        step.esignEnvelopeId = env.id;
      }
    }
  }

  // ── Views ────────────────────────────────────────────────────────────────

  private async dto(ob: ObWithSteps | null, employeeId: string): Promise<OnboardingDto> {
    const e = await this.prisma.employee.findUniqueOrThrow({ where: { id: employeeId }, include: { designation: true } });
    const documents = await this.vault.listFor(employeeId);
    const tpl = await this.templates();
    const offerDoc = { title: `Offer letter · ${e.designation?.name ?? ''}`.trim(), body: 'This letter confirms your appointment at Lexisora Infotech with the compensation shown in Annexure A.' };
    const t = await this.prisma.raw.tenant.findUnique({ where: { id: requireContext().tenantId } });
    offerDoc.body = offerDoc.body.replace('Lexisora Infotech', t?.name ?? 'the company');
    const ndaDoc = { title: 'Non-disclosure agreement', body: 'You agree to keep client code, data and business information confidential during and after employment.' };
    void tpl;
    if (!ob) {
      // Already-onboarded employee (G13): read-only summary.
      const has = (types: string[]) => documents.some((d) => types.includes(d.docType));
      const steps = ONBOARDING_STEP_KEYS.map((key, i) => ({
        key,
        order: i + 1,
        label: ONBOARDING_STEP_LABELS[key],
        status: 'DONE' as const,
        note: key === 'offer' && !has(['OFFER_LETTER']) ? 'Completed before paperless onboarding' : null,
        completedAt: e.joiningDate?.toISOString() ?? null,
        envelopeId: null,
        data: key === 'bank' ? { last4: e.bankAccountLast4, ifsc: e.bankIfsc, bank: e.bankName, taxRegime: e.taxRegime } : key === 'kit' ? { tshirtSize: e.tshirtSize } : null,
      }));
      return {
        id: '',
        employeeId,
        employeeName: e.fullName,
        empCode: e.empCode,
        designation: e.designation?.name ?? null,
        joiningDate: dbDateKey(e.joiningDate),
        status: 'COMPLETED',
        steps,
        currentStep: null,
        canFinish: false,
        incomplete: [],
        submittedAt: null,
        completedAt: e.joiningDate?.toISOString() ?? null,
        bankVerified: !!e.bankAccountLast4,
        documents,
        workMode: e.workMode,
        offerDoc,
        ndaDoc,
      };
    }
    const m = this.stepMap(ob);
    return {
      id: ob.id,
      employeeId,
      employeeName: e.fullName,
      empCode: e.empCode,
      designation: e.designation?.name ?? null,
      joiningDate: dbDateKey(e.joiningDate),
      status: ob.status,
      steps: ob.steps.map((s) => ({
        key: s.key as OnboardingStepKey,
        order: s.order,
        label: ONBOARDING_STEP_LABELS[s.key as OnboardingStepKey],
        status: s.status,
        note: s.note,
        completedAt: s.completedAt?.toISOString() ?? null,
        envelopeId: s.esignEnvelopeId,
        data: (s.data as Record<string, unknown> | null) ?? null,
      })),
      currentStep: ob.status === 'SUBMITTED' || ob.status === 'COMPLETED' ? null : currentStep(m),
      canFinish: (ob.status === 'NOT_STARTED' || ob.status === 'IN_PROGRESS') && incompleteSteps(m).length === 0,
      incomplete: incompleteSteps(m),
      submittedAt: ob.submittedAt?.toISOString() ?? null,
      completedAt: ob.completedAt?.toISOString() ?? null,
      bankVerified: !!ob.bankVerifiedAt,
      documents,
      workMode: e.workMode,
      offerDoc,
      ndaDoc,
    };
  }

  private myId() {
    const me = requireContext().employeeId;
    if (!me) throw new AppError(400, 'NO_EMPLOYEE', 'Your account is not linked to an employee record');
    return me;
  }

  async mine(): Promise<OnboardingDto> {
    const me = this.myId();
    const ob = await this.load(me);
    if (ob && ob.status !== 'COMPLETED' && ob.status !== 'CANCELLED') await this.ensureEnvelopes(ob);
    return this.dto(ob ? await this.load(me) : null, me);
  }

  async detail(employeeId: string): Promise<OnboardingDto & { bank: { holder: string | null; account: string; ifsc: string | null; bank: string | null; taxRegime: string; uan: string | null; pan: string } }> {
    const ob = await this.load(employeeId);
    const e = await this.prisma.employee.findUniqueOrThrow({ where: { id: employeeId } });
    const bankStep = ob?.steps.find((s) => s.key === 'bank');
    return {
      ...(await this.dto(ob, employeeId)),
      bank: {
        holder: ((bankStep?.data as Record<string, unknown> | null)?.holderName as string | undefined) ?? null,
        account: maskAccount(e.bankAccountLast4),
        ifsc: e.bankIfsc,
        bank: e.bankName,
        taxRegime: e.taxRegime,
        uan: e.uan,
        pan: maskPan(this.crypto.decrypt(e.panEnc)),
      },
    };
  }

  // ── Joiner actions ───────────────────────────────────────────────────────

  private async joinerOb(): Promise<ObWithSteps> {
    const me = this.myId();
    const ob = await this.load(me);
    if (!ob) throw new AppError(409, 'ONBOARDING_COMPLETED', 'Your onboarding is already complete');
    return ob;
  }

  async sign(key: 'offer' | 'nda', input: EsignInput, ua?: string) {
    const ob = await this.joinerOb();
    await this.ensureEnvelopes(ob);
    const fresh = await this.mustLoad(ob.employeeId);
    const step = fresh.steps.find((s) => s.key === key)!;
    if (key === 'nda' && this.stepMap(fresh).offer !== 'DONE') throw new AppError(409, 'OFFER_FIRST', 'Sign the offer letter first');
    if (step.status === 'DONE') return this.mine();
    if (!step.esignEnvelopeId) throw new AppError(409, 'DOC_NOT_READY', 'Your document is being prepared. Try again in a minute.');
    const { envelope } = await this.esign.sign(step.esignEnvelopeId, input, ua);
    await this.vault.add(ob.employeeId, {
      docType: key === 'offer' ? 'OFFER_LETTER' : 'NDA',
      fileId: envelope.signedFileId!,
      title: key === 'offer' ? 'Offer letter' : 'NDA',
      source: 'ESIGNED',
      verificationStatus: 'NOT_REQUIRED',
      esignEnvelopeId: envelope.id,
    });
    await this.apply(fresh, { type: 'STEP_DONE', key }, { [key]: { data: { signedAt: envelope.signedAt?.toISOString() ?? null, signedSha256: envelope.signedSha256 } } });
    if (key === 'offer') await this.prisma.jobOffer.updateMany({ where: { employeeId: ob.employeeId, status: { in: ['DRAFT', 'ISSUED'] } }, data: { status: 'ACCEPTED' } });
    await this.audit.record({ action: 'onboarding.step_completed', entity: 'Onboarding', entityId: fresh.id, meta: { step: key } });
    return this.mine();
  }

  async declineOffer(reason: string) {
    const ob = await this.joinerOb();
    const step = ob.steps.find((s) => s.key === 'offer');
    if (step?.status === 'DONE') throw new AppError(409, 'ALREADY_SIGNED', 'You have already accepted the offer');
    if (step?.esignEnvelopeId) await this.esign.decline(step.esignEnvelopeId, reason);
    await this.prisma.onboarding.update({ where: { id: ob.id }, data: { declinedReason: reason } });
    await this.prisma.jobOffer.updateMany({ where: { employeeId: ob.employeeId }, data: { status: 'DECLINED' } });
    const e = await this.prisma.employee.findUniqueOrThrow({ where: { id: ob.employeeId } });
    await this.notify.notify({ userIds: await this.notify.usersWithPermission('onboarding.manage'), type: 'people.offerDeclined', title: `${e.fullName} declined the offer`, body: reason, link: `/onboarding?employee=${e.id}`, from: 'System', email: true });
    await this.audit.record({ action: 'onboarding.offer_declined', entity: 'Onboarding', entityId: ob.id, meta: { reason } });
    return { ok: true };
  }

  async submitDocs(i: DocsStepInput) {
    const ob = await this.joinerOb();
    if (!isValidPan(i.panNumber)) throw new AppError(422, 'PAN_INVALID', 'Enter a valid PAN (5 letters, 4 digits, 1 letter; 4th letter P)');
    if (!isValidAadhaar(i.aadhaarNumber)) throw new AppError(422, 'AADHAAR_INVALID', 'Enter a valid 12-digit Aadhaar number');
    const m = this.stepMap(ob);
    if (m.offer !== 'DONE' && m.offer !== 'SKIPPED') throw new AppError(409, 'OFFER_FIRST', 'Sign the offer letter first');
    const empId = ob.employeeId;
    const docIds: string[] = [];
    docIds.push((await this.vault.add(empId, { docType: 'PAN', fileId: i.panFileId, source: 'SELF_UPLOAD' })).id);
    docIds.push((await this.vault.add(empId, { docType: 'AADHAAR', fileId: i.aadhaarFileId, source: 'SELF_UPLOAD' })).id);
    for (const [n, f] of i.marksheetFileIds.entries()) {
      docIds.push((await this.vault.add(empId, { docType: 'DEGREE', fileId: f, title: i.marksheetFileIds.length === 1 ? 'Education marksheets' : `Education marksheet ${n + 1}`, source: 'SELF_UPLOAD' })).id);
    }
    if (i.prevEmploymentFileId) docIds.push((await this.vault.add(empId, { docType: 'PREV_EMPLOYMENT', fileId: i.prevEmploymentFileId, source: 'SELF_UPLOAD' })).id);
    await this.prisma.employee.update({ where: { id: empId }, data: { panEnc: this.crypto.encrypt(i.panNumber), aadhaarEnc: this.crypto.encrypt(i.aadhaarNumber), aadhaarLast4: i.aadhaarNumber.slice(-4) } });
    await this.apply(ob, { type: 'STEP_DONE', key: 'docs' }, { docs: { data: { pan: maskPan(i.panNumber), aadhaarLast4: i.aadhaarNumber.slice(-4), documentIds: docIds } } });
    await this.audit.record({ action: 'statutory.updated', entity: 'Employee', entityId: empId, meta: { pan: maskPan(i.panNumber) } });
    return this.mine();
  }

  async submitBank(i: BankStepInput) {
    const ob = await this.joinerOb();
    const err = validateBank(i);
    if (err) throw new AppError(422, 'BANK_INVALID', err);
    const e = await this.prisma.employee.findUniqueOrThrow({ where: { id: ob.employeeId } });
    const bank = lookupIfsc(i.ifsc);
    if (i.chequeFileId) await this.vault.add(e.id, { docType: 'CANCELLED_CHEQUE', fileId: i.chequeFileId, source: 'SELF_UPLOAD' });
    await this.prisma.employee.update({
      where: { id: e.id },
      data: { bankAccountEnc: this.crypto.encrypt(i.accountNumber), bankAccountLast4: i.accountNumber.slice(-4), bankIfsc: i.ifsc, bankName: bank?.bank ?? null, taxRegime: i.taxRegime, uan: i.uan || e.uan },
    });
    await this.prisma.onboarding.update({ where: { id: ob.id }, data: { bankVerifiedAt: null, bankVerifiedBy: null } });
    const mismatch = !namesMatch(e.fullName, i.holderName);
    await this.apply(ob, { type: 'STEP_DONE', key: 'bank' }, { bank: { data: { holderName: i.holderName, last4: i.accountNumber.slice(-4), ifsc: i.ifsc, bank: bank?.bank ?? null, branch: bank?.branch ?? null, taxRegime: i.taxRegime, nameMismatch: mismatch } } });
    await this.audit.record({ action: 'bank_account.submitted', entity: 'Employee', entityId: e.id, meta: { account: maskAccount(i.accountNumber.slice(-4)), ifsc: i.ifsc } });
    return this.mine();
  }

  /** Step 5: T-shirt size → Finish. HR notified, `onboarding.completed` emitted, ID card queued. */
  async finish(i: KitStepInput) {
    const ob = await this.joinerOb();
    const e = await this.prisma.employee.findUniqueOrThrow({ where: { id: ob.employeeId } });
    const kitData = { tshirtSize: i.tshirtSize, delivery: i.delivery, address: i.address ?? null };
    const fixingKit = this.stepMap(ob).kit === 'NEEDS_ATTENTION';
    await this.apply(ob, fixingKit ? { type: 'STEP_DONE', key: 'kit' } : { type: 'FINISH' }, { kit: { data: kitData } });
    await this.prisma.employee.update({ where: { id: e.id }, data: { tshirtSize: i.tshirtSize } });
    await this.kits.setSize(e.id, i.tshirtSize, i.delivery);
    await this.idcards.ensureCard(e.id);
    await this.idcards.refresh(e.id);
    if (!fixingKit) {
      await this.notify.notify({
        userIds: await this.notify.usersWithPermission('onboarding.manage'),
        type: 'people.onboardingSubmitted',
        title: `${e.fullName} completed onboarding`,
        body: `${e.empCode} · verify documents and bank details. ID card queued, T-shirt size ${i.tshirtSize}.`,
        link: `/onboarding?employee=${e.id}`,
        from: 'System',
        email: true,
      });
      await this.notify.notify({ userIds: await this.notify.usersForEmployees([e.managerId]), type: 'people.onboardingSubmitted', title: `${e.fullName} completed onboarding`, link: `/employees/${e.id}`, from: 'HR' });
      await this.audit.record({ action: 'onboarding.submitted', entity: 'Onboarding', entityId: ob.id, meta: { tshirtSize: i.tshirtSize } });
      this.events.emit('onboarding.completed', { employeeId: e.id });
    }
    await this.maybeComplete(e.id);
    return this.mine();
  }

  // ── HR ───────────────────────────────────────────────────────────────────

  async list(status?: string): Promise<OnboardingListRow[]> {
    const obs = await this.prisma.onboarding.findMany({ where: status ? { status: status as Onboarding['status'] } : { status: { not: 'CANCELLED' } }, include: { steps: true } });
    const emps = await this.prisma.employee.findMany({ where: { id: { in: obs.map((o) => o.employeeId) } }, select: { id: true, fullName: true, empCode: true, joiningDate: true, bankAccountLast4: true, status: true } });
    const em = new Map(emps.map((e) => [e.id, e]));
    const pending = await this.prisma.employeeDocument.groupBy({ by: ['employeeId'], where: { employeeId: { in: obs.map((o) => o.employeeId) }, verificationStatus: 'PENDING', deletedAt: null, isCurrent: true }, _count: { _all: true } });
    const pm = new Map(pending.map((p) => [p.employeeId, p._count._all]));
    return obs
      .filter((o) => em.has(o.employeeId))
      .map((o) => {
        const e = em.get(o.employeeId)!;
        return {
          employeeId: e.id,
          name: e.fullName,
          empCode: e.empCode,
          joiningDate: dbDateKey(e.joiningDate),
          stepsDone: o.steps.filter((s) => s.status === 'DONE' || s.status === 'SKIPPED').length,
          docsPending: pm.get(e.id) ?? 0,
          bank: o.bankVerifiedAt ? 'Verified' : e.bankAccountLast4 ? 'Pending verification' : 'Not added',
          status: o.status,
          statusLabel: STATUS_LABEL[o.status] ?? o.status,
        };
      })
      .sort((a, b) => (b.joiningDate ?? '').localeCompare(a.joiningDate ?? ''));
  }

  async reopen(employeeId: string, key: OnboardingStepKey, reason: string) {
    const ob = await this.mustLoad(employeeId);
    if (ob.status === 'COMPLETED') throw new AppError(409, 'ONBOARDING_COMPLETED', 'Onboarding is complete; update the profile instead');
    await this.apply(ob, { type: 'REOPEN', key }, { [key]: { note: reason } });
    if (key === 'offer' || key === 'nda') {
      const step = ob.steps.find((s) => s.key === key);
      if (step?.esignEnvelopeId) await this.prisma.onboardingStep.update({ where: { id: step.id }, data: { esignEnvelopeId: null } });
    }
    await this.notify.notify({ userIds: await this.notify.usersForEmployees([employeeId]), type: 'people.onboardingReopened', title: `HR reopened “${ONBOARDING_STEP_LABELS[key]}” in your onboarding`, body: reason, link: '/onboarding', from: 'HR', email: true });
    await this.audit.record({ action: 'onboarding.reopened', entity: 'Onboarding', entityId: ob.id, meta: { step: key, reason } });
    return this.detail(employeeId);
  }

  async override(employeeId: string, reason: string) {
    const ob = await this.mustLoad(employeeId);
    await this.apply(ob, { type: 'OVERRIDE' });
    await this.prisma.onboarding.update({ where: { id: ob.id }, data: { overrideReason: reason } });
    await this.audit.record({ action: 'onboarding.override', entity: 'Onboarding', entityId: ob.id, meta: { reason } });
    return this.detail(employeeId);
  }

  async verifyBank(employeeId: string, decision: 'VERIFIED' | 'REJECTED', reason?: string | null) {
    const ctx = requireContext();
    const ob = await this.mustLoad(employeeId);
    const e = await this.prisma.employee.findUniqueOrThrow({ where: { id: employeeId } });
    if (!e.bankAccountLast4) throw badRequest('No bank details submitted yet', 'NO_BANK');
    if (decision === 'VERIFIED') {
      await this.prisma.onboarding.update({ where: { id: ob.id }, data: { bankVerifiedAt: new Date(), bankVerifiedBy: ctx.userName ?? null } });
      await this.audit.record({ action: 'bank_account.verified', entity: 'Employee', entityId: employeeId });
      await this.maybeComplete(employeeId);
    } else {
      if (!reason?.trim()) throw badRequest('Give a reason', 'REASON_REQUIRED');
      await this.reopen(employeeId, 'bank', reason);
      await this.audit.record({ action: 'bank_account.rejected', entity: 'Employee', entityId: employeeId, meta: { reason } });
    }
    return this.detail(employeeId);
  }

  /** Called after HR verifies/rejects a document. */
  async afterDocDecision(employeeId: string, decision: 'VERIFIED' | 'REJECTED', title?: string, reason?: string | null) {
    const ob = await this.load(employeeId);
    if (!ob || ob.status === 'COMPLETED' || ob.status === 'CANCELLED') return;
    if (decision === 'REJECTED') {
      await this.apply(ob, { type: 'DOC_REJECTED' }, { docs: { note: `${title ?? 'A document'} was rejected: ${reason ?? ''}`.trim() } });
    } else await this.maybeComplete(employeeId);
  }

  /** SUBMITTED → COMPLETED once every required document and the bank account are verified. */
  async maybeComplete(employeeId: string) {
    const ob = await this.load(employeeId);
    if (!ob || ob.status !== 'SUBMITTED' || !ob.bankVerifiedAt) return false;
    const open = await this.prisma.employeeDocument.count({ where: { employeeId, docType: { in: [...VERIFY_TYPES] }, isCurrent: true, deletedAt: null, verificationStatus: { in: ['PENDING', 'REJECTED'] } } });
    if (open) return false;
    await this.apply(ob, { type: 'ALL_VERIFIED' });
    await this.notify.notify({ userIds: await this.notify.usersForEmployees([employeeId]), type: 'people.onboardingCompleted', title: 'Your onboarding is complete', body: 'HR has verified your documents and bank details.', link: '/onboarding', from: 'HR' });
    await this.audit.record({ action: 'onboarding.completed', entity: 'Onboarding', entityId: ob.id });
    return true;
  }

  async cancel(employeeId: string) {
    const ob = await this.load(employeeId);
    if (!ob) return;
    await this.apply(ob, { type: 'CANCEL' });
  }

  /** Reminder job: joiners starting within 7 days with steps still open. */
  async remind() {
    const obs = await this.prisma.onboarding.findMany({ where: { status: { in: ['NOT_STARTED', 'IN_PROGRESS'] } }, include: { steps: true } });
    let sent = 0;
    for (const o of obs) {
      const e = await this.prisma.employee.findUnique({ where: { id: o.employeeId } });
      if (!e?.joiningDate) continue;
      const days = Math.round((e.joiningDate.getTime() - Date.now()) / 86400_000);
      if (![7, 3, 1].includes(days)) continue;
      const open = o.steps.filter((s) => s.status !== 'DONE' && s.status !== 'SKIPPED').map((s) => ONBOARDING_STEP_LABELS[s.key as OnboardingStepKey]);
      await this.notify.notify({ userIds: await this.notify.usersForEmployees([e.id]), type: 'people.onboardingReminder', title: `You join in ${days} day${days === 1 ? '' : 's'} · finish your onboarding`, body: `Still open: ${open.join(', ')}`, link: '/onboarding', from: 'HR', email: true });
      sent++;
    }
    return sent;
  }
}
